mapper.delete:
DELETE FROM
	CODE_DETAIL

	DOMAIN_ID = #{domainId}
	AND COMPANY_CD = #{companyCd}

mapper.select:
SELECT DOMAIN_ID , COMPANY_CD , CODE_DIV , CODE , CODE_NM , USE_YN , SORT_ORD , UPDATE_USR , UPDATE_DT , CREATE_USR , CREATE_DT FROM CODE_DETAIL
AND DOMAIN_ID = #{domainId} AND COMPANY_CD = #{companyCd} AND CODE_DIV = #{codeDiv}
AND USE_YN = #{useYn}
ORDER BY SORT_ORD
